// Procesar CSV Made for Sport con análisis inteligente
const csvText = items[0].json.data ?? items[0].json.body ?? items[0].json;
const lines = String(csvText).split(/\r?\n/);
const products = [];

function slugify(str) {
  return String(str || "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

// Función para analizar producto y asignar categoría + subcategoría
function analizarProducto(nombre, descripcion) {
  const n = nombre.toLowerCase();
  const d = (descripcion || "").toLowerCase();
  const texto = n + " " + d;

  // ═══════════════════════════════════════════════════════
  // TEXTIL
  // ═══════════════════════════════════════════════════════

  if (texto.match(/camiseta|polo|sudadera|jersey|chaleco/)) {
    return { categoryId: "textil", subcategory: "Camisetas y polos" };
  }

  if (texto.match(/pantalon|short|bermuda|leggin|malla|culotte/)) {
    return { categoryId: "textil", subcategory: "Pantalones y shorts" };
  }

  if (texto.match(/chandal|chaqueta|cortaviento|anorak/)) {
    return { categoryId: "textil", subcategory: "Chaquetas y chándales" };
  }

  if (texto.match(/zapatilla|calzado|bota|playera/)) {
    return { categoryId: "textil", subcategory: "Calzado" };
  }

  if (texto.match(/bañador|bikini|traje de baño|lycra/)) {
    return { categoryId: "textil", subcategory: "Bañadores" };
  }

  if (texto.match(/calcetin|media|tobillera/)) {
    return { categoryId: "textil", subcategory: "Calcetines" };
  }

  // ═══════════════════════════════════════════════════════
  // INSTALACIONES
  // ═══════════════════════════════════════════════════════

  if (texto.match(/red|porteria|canasta|poste|tablero/)) {
    return { categoryId: "instalaciones", subcategory: "Redes y porterías" };
  }

  if (texto.match(/colchoneta|tatami|quitamiedos|espaldera/)) {
    return { categoryId: "instalaciones", subcategory: "Colchonetas y protecciones" };
  }

  if (texto.match(/banco|banquillo|grada/)) {
    return { categoryId: "instalaciones", subcategory: "Mobiliario deportivo" };
  }

  // ═══════════════════════════════════════════════════════
  // MATERIAL ESCOLAR
  // ═══════════════════════════════════════════════════════

  if (texto.match(/psicomotricidad|sensorial|didactico/)) {
    return { categoryId: "material-escolar", subcategory: "Psicomotricidad" };
  }

  if (texto.match(/juego|ludico|recreo/)) {
    return { categoryId: "material-escolar", subcategory: "Juegos" };
  }

  // ═══════════════════════════════════════════════════════
  // DEPORTES - POR DISCIPLINA
  // ═══════════════════════════════════════════════════════

  // Tenis de mesa
  if (texto.match(/ping.*pong|tenis de mesa|donic|schildkrot|cornilleau/) ||
      (texto.match(/pelota/) && texto.match(/tenis de mesa|ping|pong/))) {
    return { categoryId: "deportes", subcategory: "Tenis de mesa" };
  }

  // Fútbol
  if (texto.match(/futbol|soccer/) || 
      (texto.match(/balon/) && texto.match(/futbol|porteria|gol/))) {
    return { categoryId: "deportes", subcategory: "Fútbol" };
  }

  // Baloncesto
  if (texto.match(/baloncesto|basket/) ||
      (texto.match(/balon/) && texto.match(/baloncesto|canasta/))) {
    return { categoryId: "deportes", subcategory: "Baloncesto" };
  }

  // Voleibol
  if (texto.match(/voleibol|voley/) ||
      (texto.match(/balon/) && texto.match(/volei|voley/))) {
    return { categoryId: "deportes", subcategory: "Voleibol" };
  }

  // Balonmano
  if (texto.match(/balonmano|handball/) ||
      (texto.match(/balon/) && texto.match(/balonmano|handball/))) {
    return { categoryId: "deportes", subcategory: "Balonmano" };
  }

  // Natación
  if (texto.match(/natacion|swimming|piscina/) ||
      texto.match(/gorra|gafas.*nata|aleta|pullboy|tabla.*nata|manguito/)) {
    return { categoryId: "deportes", subcategory: "Natación" };
  }

  // Tenis
  if (texto.match(/\btenis\b/) && !texto.match(/mesa/) ||
      (texto.match(/raqueta/) && texto.match(/tenis/)) ||
      (texto.match(/pelota/) && texto.match(/tenis/) && !texto.match(/mesa/))) {
    return { categoryId: "deportes", subcategory: "Tenis" };
  }

  // Pádel
  if (texto.match(/padel|pala de padel/)) {
    return { categoryId: "deportes", subcategory: "Pádel" };
  }

  // Bádminton
  if (texto.match(/badminton|volante|pluma/)) {
    return { categoryId: "deportes", subcategory: "Bádminton" };
  }

  // Atletismo / Running
  if (texto.match(/atletismo|running|carrera|maraton/) ||
      texto.match(/cronometro|testigo|valla.*atletismo|jabalina|disco.*atletismo/)) {
    return { categoryId: "deportes", subcategory: "Atletismo" };
  }

  // Ciclismo
  if (texto.match(/ciclismo|bicicleta|bici|cycling/)) {
    return { categoryId: "deportes", subcategory: "Ciclismo" };
  }

  // Fitness / Gimnasio
  if (texto.match(/fitness|gym|gimnasio|musculacion/) ||
      texto.match(/mancuerna|pesa|barra|disco.*fitness|kettlebell|step|bosu/)) {
    return { categoryId: "deportes", subcategory: "Fitness" };
  }

  // Yoga / Pilates
  if (texto.match(/yoga|pilates|mat|esterilla|fitball/)) {
    return { categoryId: "deportes", subcategory: "Yoga y Pilates" };
  }

  // Artes marciales
  if (texto.match(/karate|judo|taekwondo|boxeo|kimono|guante.*boxeo/)) {
    return { categoryId: "deportes", subcategory: "Artes marciales" };
  }

  // Rugby
  if (texto.match(/rugby/) || (texto.match(/balon/) && texto.match(/rugby/))) {
    return { categoryId: "deportes", subcategory: "Rugby" };
  }

  // Hockey
  if (texto.match(/hockey|stick/)) {
    return { categoryId: "deportes", subcategory: "Hockey" };
  }

  // Arbitraje
  if (texto.match(/arbitr|silbato|tarjeta.*roja|tarjeta.*amarilla|moneda.*arbitr/)) {
    return { categoryId: "deportes", subcategory: "Arbitraje" };
  }

  // ═══════════════════════════════════════════════════════
  // DEPORTES - POR TIPO DE PRODUCTO
  // ═══════════════════════════════════════════════════════

  // Balones y pelotas (genérico)
  if (texto.match(/\bbalon\b|\bpelota\b|\bball\b/)) {
    return { categoryId: "deportes", subcategory: "Balones y pelotas" };
  }

  // Accesorios genéricos
  if (texto.match(/bolsa|mochila|botella|bidon|neceser|toalla/)) {
    return { categoryId: "deportes", subcategory: "Accesorios" };
  }

  // Protecciones
  if (texto.match(/rodillera|codera|tobillera|munequera|protector|espinillera/)) {
    return { categoryId: "deportes", subcategory: "Protecciones" };
  }

  // Entrenamiento
  if (texto.match(/entrena|training|conos|pica|aros|escalera.*agilidad/)) {
    return { categoryId: "deportes", subcategory: "Entrenamiento" };
  }

  // Cronometraje
  if (texto.match(/cronometro|temporizador|marcador/)) {
    return { categoryId: "deportes", subcategory: "Cronometraje" };
  }

  // DEFAULT: Otros deportes
  return { categoryId: "deportes", subcategory: "Otros deportes" };
}

for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;

  const fields = line.split(";");
  const cleanFields = fields.map((field) => field.replace(/"/g, "").trim());

  const name = cleanFields[0] || "";
  const price = parseFloat(cleanFields[1]) || 0;
  const refProveedor = cleanFields[2] || null;
  const ean = cleanFields[3] || null;
  const stock = parseInt(cleanFields[4], 10) || 0;
  const description = cleanFields[5] || "";
  const imagenesStr = cleanFields[6] || "";

  const imagenes = imagenesStr
    .split(",")
    .map((url) => url.trim())
    .filter((url) => url.length > 0);

  const skuInterno = `MF${refProveedor}`;
  const baseSlug = slugify(name);
  const slug = `${baseSlug}-${slugify(skuInterno)}`;

  // Análisis inteligente
  const analisis = analizarProducto(name, description);

  products.push({
    json: {
      proveedor: "made_for_sport",
      ref_proveedor: refProveedor,
      ref_variante: null,
      ean,
      stock,
      name,
      description,
      price,
      imagenes,
      slug,
      sku_interno: skuInterno,
      categoryId: analisis.categoryId,
      subcategory: analisis.subcategory,
      marca: null,
      categoria: null,
      categoria_padre: null,
      color: null,
      talla: null,
      published: true,
      activo: true,
      visible_web: true,
    },
  });
}

return products;

// Aplicar márgenes dinámicos a precios de Made for Sport
function calcularPrecioConMargen(precioBase) {
  const precio = parseFloat(precioBase);
  if (isNaN(precio) || precio <= 0) {
    return { precioBase: 0, precioFinal: 0 };
  }
  let multiplicador;
  if (precio < 50) multiplicador = 1.50;
  else if (precio < 100) multiplicador = 1.47;
  else if (precio < 200) multiplicador = 1.43;
  else if (precio < 400) multiplicador = 1.38;
  else multiplicador = 1.30;
  const precioFinal = Math.round(precio * multiplicador * 1.21 * 100) / 100;
  return { precioBase: Math.round(precio * 100) / 100, precioFinal };
}
const results = [];
for (const item of items) {
  const precios = calcularPrecioConMargen(item.json.price);
  results.push({ json: { ...item.json, precioBase: precios.precioBase, price: precios.precioFinal } });
}
return results;
